65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
73	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
74	     * address shape rather than full RFC 5322 conformance.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Disposable email domains that are not accepted for an owner's email. An email whose domain
81	     * (the part after the {@code @}, compared case-insensitively) is on this blocklist is rejected.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
84	        "mailinator.com",
85	        "tempmail.com",
86	        "guerrillamail.com");
87	
88	    /**
89	     * Dedicated audit logger. Successful owner creation emits a single line here carrying the new
90	     * owner's id, customer code and registration date so the side-effect can be observed
91	     * independently of the HTTP response.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys and values are
97	     * upper-cased so the mapping is applied after the address has been upper-cased.
98	     */
99	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
100	        "ST", "STREET",
101	        "RD", "ROAD",
102	        "AVE", "AVENUE");
103	
104	    /**
105	     * Maximum number of owners permitted in a single city. Once a city already contains this many
106	     * owners, creating another owner in that city is rejected as a conflict.
107	     */
108	    private static final int CITY_CAPACITY = 50;
109	
110	    /**
111	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
112	     * already share the current registration date, creating another owner today is rejected.
113	     */
114	    private static final int DAILY_OWNER_LIMIT = 100;
115	
116	    /**
117	     * Number of owner registrations on a single business day above which a newly created owner is
118	     * flagged with {@code bulkSignupWarning=true}. Once more than this many owners already share the
119	     * registration date, the surge is signalled in the response; the create itself still succeeds.
120	     */
121	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
122	
123	    /**
124	     * Fixed city-to-region table used to validate an owner's postcode. Mirrors the mapping used to
125	     * derive an owner's locality ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD});
126	     * a city that is not listed has no known region and accepts any 4-digit postcode.
127	     */
128	    private static final Map<String, String> CITY_REGIONS = Map.of(
129	        "Sydney", "NSW",
130	        "Melbourne", "VIC",
131	        "Brisbane", "QLD");
132	
133	    /**
134	     * Region to inclusive 4-digit postcode range {@code {low, high}}: NSW 2000-2099, VIC 3000-3099,
135	     * QLD 4000-4099. A supplied postcode outside its city's region range is rejected.
136	     */
137	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
138	        "NSW", new int[] {2000, 2099},
139	        "VIC", new int[] {3000, 3099},
140	        "QLD", new int[] {4000, 4099});
141	
142	    private final ClinicService clinicService;
143	
144	    private final OwnerMapper ownerMapper;
145	
146	    private final PetMapper petMapper;
147	
148	    private final VisitMapper visitMapper;
149	
150	    public OwnerRestControllerV1(ClinicService clinicService,
151	                                 OwnerMapper ownerMapper,
152	                                 PetMapper petMapper,
153	                                 VisitMapper visitMapper) {
154	        this.clinicService = clinicService;
155	        this.ownerMapper = ownerMapper;
156	        this.petMapper = petMapper;
157	        this.visitMapper = visitMapper;
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
163	        Collection<Owner> owners;
164	        if (lastName != null) {
165	            owners = this.clinicService.findOwnerByLastName(lastName);
166	        } else {
167	            owners = this.clinicService.findAllOwners();
168	        }
169	        if (owners.isEmpty()) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
178	        Owner owner = this.clinicService.findOwnerById(ownerId);
179	        if (owner == null) {
180	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
181	        }
182	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
183	    }
184	
185	    /**
186	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
187	     * upper-cases the value, and expands common street-type abbreviations word-by-word
188	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
189	     * normalizes to the empty string. The normalized value is what the application stores, returns
190	     * and compares for household detection.
191	     *
192	     * @param address the raw address value from the request, may be {@code null}
193	     * @return the normalized address, or the empty string when none was supplied
194	     */
195	    private String normalizeAddress(String address) {
196	        if (address == null) {
197	            return "";
198	        }
199	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
200	        if (collapsed.isEmpty()) {
201	            return "";
202	        }
203	        String[] tokens = collapsed.split(" ");
204	        StringBuilder normalized = new StringBuilder();
205	        for (int i = 0; i < tokens.length; i++) {
206	            if (i > 0) {
207	                normalized.append(' ');
208	            }
209	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
210	        }
211	        return normalized.toString();
212	    }
213	
214	    /**
215	     * Applies address normalization to whichever address form the request supplied, preferring the
216	     * structured fields. When a non-blank {@code addressLine1} is present the structured form wins:
217	     * {@code addressLine1} (and {@code addressLine2} when present) are normalized in place, and the
218	     * flat {@code address} is set to the composed value - the normalized {@code addressLine1} with,
219	     * when an {@code addressLine2} was supplied, a single space and the normalized {@code addressLine2}
220	     * appended - so everything downstream that reads {@code address} sees the structured value. When
221	     * no {@code addressLine1} is supplied the flat {@code address} is normalized as before, keeping
222	     * earlier minimal owners backward-compatible.
223	     *
224	     * @param ownerFieldsDto the owner payload whose address fields are normalized in place
225	     */
226	    private void applyAddressFields(OwnerFieldsDto ownerFieldsDto) {
227	        if (StringUtils.hasText(ownerFieldsDto.getAddressLine1())) {
228	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
229	            ownerFieldsDto.setAddressLine1(line1);
230	            if (StringUtils.hasText(ownerFieldsDto.getAddressLine2())) {
231	                String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
232	                ownerFieldsDto.setAddressLine2(line2);
233	                ownerFieldsDto.setAddress(line1 + " " + line2);
234	            } else {
235	                ownerFieldsDto.setAddressLine2(null);
236	                ownerFieldsDto.setAddress(line1);
237	            }
238	        } else {
239	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
240	        }
241	    }
242	
243	    /**
244	     * Rejects an owner payload that is missing or blank in any required field. The response body's
245	     * {@code errors} array lists the name of each offending field.
246	     *
247	     * @param ownerFieldsDto the owner payload to validate
248	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
249	     */
250	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
251	        List<String> missingFields = new ArrayList<>();
252	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
253	            missingFields.add("firstName");
254	        }
255	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
256	            missingFields.add("lastName");
257	        }
258	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
259	            missingFields.add("address");
260	        }
261	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
262	            missingFields.add("city");
263	        }
264	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
265	            missingFields.add("telephone");
266	        }
267	        if (!missingFields.isEmpty()) {
268	            throw new RequiredFieldsMissingException(missingFields);
269	        }
270	    }
271	
272	    /**
273	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
274	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
275	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
276	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
277	     * region accepts any 4-digit postcode.
278	     *
279	     * @param postcode the raw postcode value from the request, may be {@code null}
280	     * @param city the owner's city, used to look up the region whose range constrains the postcode
281	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
282	     */
283	    private void validatePostcode(String postcode, String city) {
284	        if (postcode == null) {
285	            return;
286	        }
287	        if (!postcode.matches("[0-9]{4}")) {
288	            throw new InvalidFieldsException(List.of("postcode"));
289	        }
290	        String region = CITY_REGIONS.get(city);
291	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
292	        if (range != null) {
293	            int value = Integer.parseInt(postcode);
294	            if (value < range[0] || value > range[1]) {
295	                throw new InvalidFieldsException(List.of("postcode"));
296	            }
297	        }
298	    }
299	
300	    /**
301	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
302	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
303	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
304	     * followed by 8 to 15 digits.
305	     *
306	     * @param telephone the raw telephone value from the request
307	     * @return the E.164 telephone (e.g. {@code +61412345678})
308	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
309	     */
310	    private String normalizeTelephone(String telephone) {
311	        if (telephone == null) {
312	            throw new InvalidFieldsException(List.of("telephone"));
313	        }
314	        String trimmed = telephone.trim();
315	        boolean international = trimmed.startsWith("+");
316	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
317	        String digits;
318	        if (international) {
319	            digits = cleaned.substring(1);
320	        } else {
321	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
322	            digits = "61" + national;
323	        }
324	        if (!digits.matches("[0-9]{8,15}")) {
325	            throw new InvalidFieldsException(List.of("telephone"));
326	        }
327	        requireValidNationalLength(digits);
328	        return "+" + digits;
329	    }
330	
331	    /**
332	     * Country codes with a fixed national-number length, checked longest-prefix first so that
333	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
334	     * digits; the North American Numbering Plan ('1') requires 10.
335	     */
336	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
337	
338	    /**
339	     * Validates that the national number (the E.164 digits after the country code) has the length
340	     * required for its country. Country codes without a known fixed length are left to the general
341	     * E.164 length check.
342	     *
343	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
344	     * @throws InvalidFieldsException if the national number is the wrong length for its country
345	     */
346	    private void requireValidNationalLength(String digits) {
347	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
348	            .filter(entry -> digits.startsWith(entry.getKey()))
349	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
350	            .ifPresent(entry -> {
351	                int nationalLength = digits.length() - entry.getKey().length();
352	                if (nationalLength != entry.getValue()) {
353	                    throw new InvalidFieldsException(List.of("telephone"));
354	                }
355	            });
356	    }
357	
358	    /**
359	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
360	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
361	     * be a syntactically valid address; the accepted value is returned lower-cased.
362	     *
363	     * @param email the raw email value from the request, may be {@code null}
364	     * @return the lower-cased email, or {@code null} when none was supplied
365	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
366	     */
367	    private String normalizeEmail(String email) {
368	        if (email == null || email.isBlank()) {
369	            return null;
370	        }
371	        String trimmed = email.trim();
372	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
373	            throw new InvalidFieldsException(List.of("email"));
374	        }
375	        String normalized = trimmed.toLowerCase(Locale.ROOT);
376	        String domain = normalized.substring(normalized.indexOf('@') + 1);
377	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
378	            throw new InvalidFieldsException(List.of("email"));
379	        }
380	        return normalized;
381	    }
382	
383	    /**
384	     * Rejects an owner that collides with an existing owner on their derived identity key. All
385	     * duplicate detection is consolidated into this single key
386	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
387	     * the former separate telephone, email and household checks.
388	     *
389	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
390	     * share the same normalized telephone. Because the telephone is the leading, always-present part
391	     * of the key, two members of the same household with <em>different</em> telephones have different
392	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
393	     * scenario in the acceptance suite exercises - is rejected.
394	     *
395	     * @param owner the owner being created, with its normalized telephone and email already applied
396	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
397	     */
398	    private void requireUniqueIdentity(Owner owner) {
399	        String telephone = owner.getTelephone();
400	        boolean taken = this.clinicService.findAllOwners().stream()
401	            .map(Owner::getTelephone)
402	            .anyMatch(existing -> existing != null && existing.equals(telephone));
403	        if (taken) {
404	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
405	        }
406	    }
407	
408	    /**
409	     * Rejects an owner that would join an existing owner's household without opting in. The household
410	     * is keyed by the owner's computed {@link OwnerMapper#householdId(Owner) household id} - the first
411	     * 12 hex characters of SHA-256 over the normalized last name and postcode - so two owners sharing
412	     * a last name and postcode belong to the same household even with different addresses or
413	     * telephones. Only owners with a postcode participate: an owner without a postcode has no
414	     * well-defined household and is never blocked here. The check is bypassed by the caller when the
415	     * request sets {@code sharesHousehold}, so a declared household member is created rather than
416	     * rejected.
417	     *
418	     * @param owner the owner being created, with its normalized fields already applied
419	     * @throws DuplicateOwnerHouseholdException if an existing owner already shares the household id
420	     */
421	    private void requireNoHouseholdDuplicate(Owner owner) {
422	        if (owner.getPostcode() == null) {
423	            return;
424	        }
425	        String householdId = ownerMapper.householdId(owner);
426	        boolean taken = this.clinicService.findAllOwners().stream()
427	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
428	        if (taken) {
429	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getPostcode());
430	        }
431	    }
432	
433	    /**
434	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
435	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
436	     * normalizes to the empty string.
437	     *
438	     * @param value the raw field value, may be {@code null}
439	     * @return the trimmed, whitespace-collapsed, lower-cased form
440	     */
441	    private String normalizeHousehold(String value) {
442	        if (value == null) {
443	            return "";
444	        }
445	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
446	    }
447	
448	    /**
449	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
450	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
451	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
452	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
453	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
454	     * returned so the result is deterministic.
455	     *
456	     * @param owner the owner being created, with its normalized telephone already applied
457	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
458	     */
459	    private Owner findPossibleDuplicate(Owner owner) {
460	        String lastName = owner.getLastName();
461	        String postcode = owner.getPostcode();
462	        if (lastName == null || postcode == null) {
463	            return null;
464	        }
465	        String telephone = owner.getTelephone();
466	        return this.clinicService.findAllOwners().stream()
467	            .filter(existing -> postcode.equals(existing.getPostcode()))
468	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
469	            .filter(existing -> existing.getTelephone() == null
470	                || !existing.getTelephone().equals(telephone))
471	            .min(Comparator.comparingInt(Owner::getId))
472	            .orElse(null);
473	    }
474	
475	    /**
476	     * Rejects an owner whose city already contains the maximum permitted number of owners
477	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
478	     * the same normalization used for the other owner household fields.
479	     *
480	     * @param city the city of the owner being created
481	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
482	     */
483	    private void requireCityHasCapacity(String city) {
484	        String normalizedCity = normalizeHousehold(city);
485	        long count = this.clinicService.findAllOwners().stream()
486	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
487	            .count();
488	        if (count >= CITY_CAPACITY) {
489	            throw new CityAtCapacityException(city);
490	        }
491	    }
492	
493	    /**
494	     * Rejects creating an owner once the given business day has already reached the maximum
495	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
496	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
497	     * registration date.
498	     *
499	     * @param registrationDate the business-day-adjusted registration date of the owner being created
500	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
501	     *     registered on that business day
502	     */
503	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
504	        long count = this.clinicService.findAllOwners().stream()
505	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
506	            .count();
507	        if (count >= DAILY_OWNER_LIMIT) {
508	            throw new DailyOwnerLimitException(registrationDate);
509	        }
510	    }
511	
512	    /**
513	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
514	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
515	     * been registered on that date. Evaluated before the new owner is persisted, so the count
516	     * reflects the owners that existed at the time of creation.
517	     *
518	     * @param registrationDate the business-day-adjusted registration date of the owner being created
519	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
520	     *     that registration date, otherwise {@code false}
521	     */
522	    private boolean isBulkSignup(LocalDate registrationDate) {
523	        long count = this.clinicService.findAllOwners().stream()
524	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
525	            .count();
526	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
527	    }
528	
529	    /**
530	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
531	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
532	     * date in the future is invalid.
533	     *
534	     * @param registrationDate the registration date supplied on the request, may be {@code null}
535	     * @throws InvalidFieldsException if the supplied date is later than today's server date
536	     */
537	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
538	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
539	            throw new InvalidFieldsException(List.of("registrationDate"));
540	        }
541	    }
542	
543	    /**
544	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
545	     * following Monday, while a weekday is returned unchanged.
546	     *
547	     * @param date the effective registration date (supplied or defaulted to the server date)
548	     * @return the same date when it is a weekday, otherwise the next Monday
549	     */
550	    private LocalDate toBusinessDay(LocalDate date) {
551	        return switch (date.getDayOfWeek()) {
552	            case SATURDAY -> date.plusDays(2);
553	            case SUNDAY -> date.plusDays(1);
554	            default -> date;
555	        };
556	    }
557	
558	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
559	    @Override
560	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
561	        applyAddressFields(ownerFieldsDto);
562	        validateRequiredFields(ownerFieldsDto);
563	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
564	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
565	        requireCityHasCapacity(ownerFieldsDto.getCity());
566	        String email = normalizeEmail(ownerFieldsDto.getEmail());
567	        HttpHeaders headers = new HttpHeaders();
568	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
569	        owner.setTelephone(telephone);
570	        owner.setEmail(email);
571	        requireUniqueIdentity(owner);
572	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
573	        if (!sharesHousehold) {
574	            requireNoHouseholdDuplicate(owner);
575	        }
576	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
577	        LocalDate effectiveDate = owner.getRegistrationDate() != null
578	            ? owner.getRegistrationDate() : LocalDate.now();
579	        LocalDate registrationDate = toBusinessDay(effectiveDate);
580	        owner.setRegistrationDate(registrationDate);
581	        requireDailyLimitNotReached(registrationDate);
582	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
583	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
584	        owner.setPossibleDuplicate(possibleDuplicate != null);
585	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
586	        this.clinicService.saveOwner(owner);
587	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
588	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
589	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
590	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
591	        headers.setLocation(UriComponentsBuilder.newInstance()
592	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
593	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
594	    }
595	
596	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
597	    @Override
598	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
599	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
600	        if (currentOwner == null) {
601	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
602	        }
603	        currentOwner.setAddress(ownerFieldsDto.getAddress());
604	        currentOwner.setCity(ownerFieldsDto.getCity());
605	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
606	        currentOwner.setLastName(ownerFieldsDto.getLastName());
607	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
608	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
609	        this.clinicService.saveOwner(currentOwner);
610	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
611	    }
612	
613	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
614	    @Transactional
615	    @Override
616	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
617	        Owner owner = this.clinicService.findOwnerById(ownerId);
618	        if (owner == null) {
619	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
620	        }
621	        this.clinicService.deleteOwner(owner);
622	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
623	    }
624	
625	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
626	    @Override
627	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
628	        Owner owner = this.clinicService.findOwnerById(ownerId);
629	        if (owner == null) {
630	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
631	        }
632	        HttpHeaders headers = new HttpHeaders();
633	        Pet pet = petMapper.toPet(petFieldsDto);
634	        owner.setId(ownerId);
635	        pet.setOwner(owner);
636	        pet.getType().setName(null);
637	        this.clinicService.savePet(pet);
638	        PetDto petDto = petMapper.toPetDto(pet);
639	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
640	            .buildAndExpand(pet.getId()).toUri());
641	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
642	    }
643	
644	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
645	    @Override
646	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
647	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
648	        if (currentOwner != null) {
649	            Pet currentPet = this.clinicService.findPetById(petId);
650	            if (currentPet != null) {
651	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
652	                currentPet.setName(petFieldsDto.getName());
653	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
654	                this.clinicService.savePet(currentPet);
655	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
656	            }
657	        }
658	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
659	    }
660	
661	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
662	    @Override
663	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
664	        HttpHeaders headers = new HttpHeaders();
665	        Visit visit = visitMapper.toVisit(visitFieldsDto);
666	        Pet pet = new Pet();
667	        pet.setId(petId);
668	        visit.setPet(pet);
669	        this.clinicService.saveVisit(visit);
670	        VisitDto visitDto = visitMapper.toVisitDto(visit);
671	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
672	            .buildAndExpand(visit.getId()).toUri());
673	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
674	    }
675	
676	
677	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
678	    @Override
679	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
680	        Owner owner = this.clinicService.findOwnerById(ownerId);
681	        if (owner != null) {
682	            Pet pet = owner.getPet(petId);
683	            if (pet != null) {
684	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
685	            }
686	        }
687	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
688	    }
689	}
